-- 1134: Blog post — "AI-900 Azure AI Fundamentals in Singapore: Course, Funding and What Replaced the Exam"
--
--       Lead-in post for WSQ - Microsoft Azure AI Fundamentals (AI-900) (TGS-2023021100).
--       Backdated to 2025-09-02 (published, status 1). No LinkedIn / Facebook share is
--       performed: linkedin_urn carries the manual-skip sentinel and the post ships
--       already-published, so publishDue never picks it up.
--
-- Every figure below was read off the LIVE course page on 2026-08-26, not invented:
--   * Fee card: full $800.00, GST $72.00 (9%), baseline nett $472.00
--     (SG/PR 21+, 50%), MCES/SME nett $312.00 (SG 40+, 70%).
--   * Course information: 2 days / 16 hrs, Beginner, 2 hrs assessment.
--   * Funding validity 17 May 2023 - 16 May 2027; Absentee Payroll $4.50/hr.
--   * Skills Framework: Artificial Intelligence Application in Product Development (ICT-TEM-3034-1.1).
--   * Exam weightings from the official study guide, skills measured as of 2 May 2025.
--   * NOTE: the AI-900 exam RETIRED on 30 June 2026. The post says so plainly in a
--     notice near the top, in the FAQ, and in the meta description, and it does NOT tell
--     readers to book the exam. The WSQ course itself still runs and is still funded.
--   * Practice-exam URL verified HTTP 200: https://exams.tertiaryinfotech.com/practice-exams/microsoft/microsoft-ai-900
--
-- Notes for future editors:
--  * apply.php splits statements on ";" at end-of-line — the content HTML below is ONE line.
--  * Idempotent: WHERE NOT EXISTS on url_key, INSERT IGNORE on tag links. Safe to re-run.
--  * SG-only guard via @mms_instance — the CTA course is SG WSQ, absent on MY/GH.
--  * hero_image_url is NOT set here (SQL cannot render one) — generate on prod post-deploy.

SET @is_sg := IF(@mms_instance = 'SG', 1, 0);

INSERT INTO `mmd_blog_post` (`title`, `url_key`, `excerpt`, `content`, `author`, `status`, `published_at`, `related_skus`, `source_sku`, `meta_title`, `meta_description`, `meta_keywords`, `linkedin_urn`, `created_at`, `updated_at`) SELECT 'AI-900 Azure AI Fundamentals in Singapore: Course, Funding and What Replaced the Exam', 'ai-900-azure-ai-fundamentals-singapore-guide', 'The AI-900 exam retired on 30 June 2026, but the WSQ course still runs and is still funded &mdash; $472 nett, or $312 for Singapore Citizens aged 40 and above. Here is what the course covers and what the current alternatives are.', '<div class="mmd-summary"><div class="mmd-summary-label">Summary</div><p><strong>AI-900</strong> is the Microsoft credential for anyone who needs to discuss AI systems credibly without being an engineer. This guide covers what the exam measures, what the 2 days WSQ course covers, and what you pay after SkillsFuture funding &mdash; <strong>$472</strong> for Singapore Citizens and PRs aged 21 and above, or <strong>$312</strong> for Singapore Citizens aged 40 and above.</p></div><p><strong>Please note:</strong> the <strong>AI-900</strong> certification exam was retired by Microsoft on <strong>30 June 2026</strong>. Microsoft has replaced it with <strong>AI-901</strong>, which leads to the same certification. The WSQ course below still runs, is still funded, and still leads to a WSQ Statement of Attainment &mdash; the skills it teaches are unchanged. What has changed is that this particular Microsoft exam can no longer be booked. <a href="https://www.tertiarycourses.com.sg/microsoft-certifications-exams.html">See the current Microsoft certification courses</a>.</p><h2>Why AI-900 is worth taking</h2><p>Every organisation in Singapore is now being asked what its AI strategy is, and the people answering are rarely machine-learning specialists. They are product owners, compliance officers, operations managers and IT generalists who need to know what a model can and cannot do, where the data goes, and which Azure service fits which problem. AI-900 was built for exactly that audience.</p><ul><li><strong>No coding or data-science background needed.</strong> It is the one Azure AI credential you can sit without proving anything else first.</li><li><strong>It teaches vocabulary, not just tools.</strong> Computer vision, NLP, generative AI and responsible-AI principles are all covered at a level that makes technical conversations productive.</li><li><strong>It is the gateway to AI-102.</strong> The engineer-level Azure AI certification assumes the concepts AI-900 teaches.</li><li><strong>Fundamentals certifications never expire</strong>, unlike role-based Microsoft certifications which renew annually.</li></ul><p>The course is mapped to the Skills Framework under <strong>Artificial Intelligence Application in Product Development</strong> (TSC code ICT-TEM-3034-1.1), and leads to roles such as AI Developer, Cloud Solutions Architect, Data Scientist, Machine Learning Engineer. <a href="https://www.tertiarycourses.com.sg/wsq-microsoft-azure-ai-fundamentals-ai-900.html">Check the funding you qualify for</a>.</p><h2>The AI-900 exam at a glance</h2><table><tbody><tr><td>Exam</td><td>AI-900: Microsoft Azure AI Fundamentals</td></tr><tr><td>Status</td><td><strong>Retired on 30 June 2026</strong></td></tr><tr><td>Replaced by</td><td>AI-901 (same certification: Azure AI Fundamentals)</td></tr><tr><td>Passing score</td><td>700 out of 1000 (scaled)</td></tr><tr><td>Certification</td><td>Fundamentals certifications do not expire</td></tr></tbody></table><h2>AI-900 exam domains and weightings</h2><p>These are the skills measured on the official study guide. The weightings tell you where to spend your revision time.</p><table><thead><tr><th>Skills measured</th><th>Weighting</th></tr></thead><tbody><tr><td>Describe AI workloads and considerations</td><td>15&ndash;20%</td></tr><tr><td>Describe fundamental principles of machine learning on Azure</td><td>15&ndash;20%</td></tr><tr><td>Describe features of computer vision workloads on Azure</td><td>15&ndash;20%</td></tr><tr><td>Describe features of NLP workloads on Azure</td><td>15&ndash;20%</td></tr><tr><td>Describe features of generative AI workloads on Azure</td><td>20&ndash;25%</td></tr></tbody></table><p><em>Source: official Microsoft study guide, skills measured as of 2 May 2025.</em></p><h2>What the WSQ course covers</h2><p>The 2 days (16 hrs) <a href="https://www.tertiarycourses.com.sg/wsq-microsoft-azure-ai-fundamentals-ai-900.html"><strong>WSQ - Microsoft Azure AI Fundamentals (AI-900)</strong></a> course is pitched at <strong>Beginner</strong> level and is delivered in our Woodlands classroom with hands-on labs, followed by a 2 hrs assessment. The outline tracks the official objectives:</p><ol><li>Get started with AI and AutoML on Azure</li><li>Computer Vision and Natural Language Processing</li><li>Anomaly Detector</li><li>Knowledge Mining and Cognitive Search</li></ol><h2>Practise what you learn</h2><p>Course participants get free, unlimited access to our <a href="https://exams.tertiaryinfotech.com/practice-exams/microsoft/microsoft-ai-900">AI-900 practice exams</a> on the Tertiary Infotech Practice Exam Portal, in both Practice Mode (with instant explanations) and timed Exam Mode. The portal offers non-participants 10 free questions per exam.</p><h2>What you actually pay: funding for AI-900 training</h2><p>The full fee is $800 before GST. As an SWDA-funded WSQ course, the subsidy depends on your citizenship, age and who is sponsoring you:</p><table><thead><tr><th>Who you are</th><th>Subsidy</th><th>You pay (incl. GST)</th></tr></thead><tbody><tr><td>Non-funded / international participants</td><td>&ndash;</td><td>$872</td></tr><tr><td>Singapore Citizen or PR, aged 21 and above</td><td>50%</td><td><strong>$472</strong></td></tr><tr><td>Singapore Citizen aged 40 and above (MCES), or SME-sponsored</td><td>70%</td><td><strong>$312</strong></td></tr></tbody></table><p><em>GST of $72 is charged at 9% on the full course fee of $800, as required for SWDA-funded courses &mdash; the subsidy applies to the course fee, not the tax.</em></p><p>Funding for this course is valid from <strong>17 May 2023</strong> to <strong>16 May 2027</strong>. You must register and complete the course within that window to qualify.</p><div class="mmd-faq"><details class="mmd-faq-item"><summary class="mmd-faq-q">1. SkillsFuture Credit (SFC)</summary><div class="mmd-faq-a"><p>Singaporeans aged 25 and above have an opening SkillsFuture Credit of $500 plus any top-ups, and those aged 40 and above received a $4,000 Mid-Career top-up. Credit can offset the fee payable after subsidy, though the Mid-Career top-up cannot be used on this course. <a href="https://www.tertiarycourses.com.sg/how-to-claim-skillsfuture-credit.html">How to claim SkillsFuture Credit</a>.</p></div></details><details class="mmd-faq-item"><summary class="mmd-faq-q">2. SkillsFuture Enterprise Credit (SFEC)</summary><div class="mmd-faq-a"><p>Eligible employers can draw on SFEC to cover out-of-pocket costs when sponsoring staff. See our <a href="https://www.tertiarycourses.com.sg/sfec.html">SFEC guide</a> for who qualifies and how to claim.</p></div></details><details class="mmd-faq-item"><summary class="mmd-faq-q">3. PSEA</summary><div class="mmd-faq-a"><p>Singapore Citizens can use Post-Secondary Education Account funds to offset the fee payable after subsidy. This course carries the PSEA tag, so it is eligible.</p></div></details><details class="mmd-faq-item"><summary class="mmd-faq-q">4. UTAP</summary><div class="mmd-faq-a"><p>NTUC members can claim 50% of the unfunded fee under UTAP, capped at $250 a year, or $500 a year for members aged 40 and above. See the <a href="https://www.tertiarycourses.com.sg/utap.html">UTAP guide</a>.</p></div></details><details class="mmd-faq-item"><summary class="mmd-faq-q">5. Absentee Payroll</summary><div class="mmd-faq-a"><p>Employers sponsoring staff can claim Absentee Payroll at $4.50 an hour, capped at $100,000 per enterprise per year, for the hours staff spend in training.</p></div></details></div><p><a href="https://www.tertiarycourses.com.sg/wsq-microsoft-azure-ai-fundamentals-ai-900.html"><strong>See the live fee breakdown for your profile &rarr;</strong></a></p><h2>How to get started</h2><ol><li><strong>Register for the 2 days WSQ course.</strong> Pick an intake on the <a href="https://www.tertiarycourses.com.sg/wsq-microsoft-azure-ai-fundamentals-ai-900.html">course page</a> and apply your funding at checkout.</li><li><strong>Attend and complete the assessment.</strong> You need at least 75% attendance and a pass in the 2 hrs assessment to receive your WSQ Statement of Attainment.</li><li><strong>Rehearse on the practice exams</strong> until you are consistently clearing the pass mark under timed conditions.</li></ol><h2>Where to go after AI-900</h2><p>The natural next step is <a href="https://www.tertiarycourses.com.sg/wsq-microsoft-certified-azure-ai-engineer-associate-ai-102-training.html">AI-102, the Azure AI Engineer Associate</a>, which moves from describing AI services to building with them. If your interest is data rather than AI, DP-900 covers the data platform underneath. Browse the full <a href="https://www.tertiarycourses.com.sg/microsoft-certifications-exams.html">Microsoft certification course catalogue</a> to plan the next rung.</p><h2>Frequently asked questions</h2><div class="mmd-faq"><details class="mmd-faq-item"><summary class="mmd-faq-q">Do I need programming experience to take this course?</summary><div class="mmd-faq-a"><p>No. The course and the exam are designed for candidates from both technical and non-technical backgrounds. You should be comfortable using a computer, but no coding is required.</p></div></details><details class="mmd-faq-item"><summary class="mmd-faq-q">Is the Microsoft exam fee included in the course fee?</summary><div class="mmd-faq-a"><p>No. The WSQ course fee covers the training and the WSQ assessment. The Microsoft certification exam is booked and paid for separately through Pearson VUE.</p></div></details><details class="mmd-faq-item"><summary class="mmd-faq-q">Will I get a certificate from this course?</summary><div class="mmd-faq-a"><p>Yes. On completing the course and passing the assessment with at least 75% attendance, you receive a WSQ Statement of Attainment, which is a nationally recognised qualification in Singapore.</p></div></details><details class="mmd-faq-item"><summary class="mmd-faq-q">Can I use SkillsFuture Credit to pay for this course?</summary><div class="mmd-faq-a"><p>Yes. SkillsFuture Credit can offset the fee payable after the WSQ subsidy. Singapore Citizens aged 25 and above have credit available to use.</p></div></details><details class="mmd-faq-item"><summary class="mmd-faq-q">How long is the course and when does it run?</summary><div class="mmd-faq-a"><p>The course runs over 2 days (16 hours) in our Woodlands training centre. Upcoming intake dates are listed on the course page.</p></div></details></div><h2>Register for Azure AI Fundamentals training</h2><p>Seats are limited and classes fill ahead of each intake. View upcoming dates and reserve your place on the <a href="https://www.tertiarycourses.com.sg/wsq-microsoft-azure-ai-fundamentals-ai-900.html"><strong>WSQ - Microsoft Azure AI Fundamentals (AI-900)</strong></a> course page, or call us on +65 6100 0613 if you would like your funding worked out first.</p>', 'Tertiary Infotech Academy', 1, '2025-09-02', 'TGS-2023021100', 'TGS-2023021100', 'AI-900 Course Singapore | Azure AI Fundamentals | WSQ Funding', 'AI-900 Azure AI Fundamentals in Singapore. The AI-900 exam retired on 30 June 2026; the WSQ course still runs from $312 nett after funding. Full details and current alternatives.', 'ai-900 course singapore, azure ai fundamentals certification, ai-900 exam, wsq microsoft course, skillsfuture microsoft certification, microsoft certification singapore, ai-900 funding, ai-900 training singapore', 'manual-skip-no-share', '2025-09-02 09:00:00', '2025-09-02 09:00:00' FROM DUAL WHERE @is_sg > 0 AND NOT EXISTS (SELECT 1 FROM `mmd_blog_post` WHERE `url_key` = 'ai-900-azure-ai-fundamentals-singapore-guide');

